sys_script_include.script:
var PCLineUserInfo = Class.create();
PCLineUserInfo.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

  // Client-callable entry (GlideAjax)
  byUser: function () {
    var uid = this.getParameter('sysparm_user') || gs.getUserID();
    return this._payload(uid);
  },

  // Server-side convenience method (for Scripts - Background)
  byUserId: function (uid) {
    return this._payload(uid || gs.getUserID());
  },

  _payload: function (uid) {
    var out = { email: '', manager: '', manager_email: '' };

    var u = new global.GlideRecord('sys_user');
    if (u.get(uid)) {
      out.email = u.getValue('email') || '';
      var mid = u.getValue('manager');
      if (mid) {
        out.manager = mid;                           // sys_id of manager
        var m = new global.GlideRecord('sys_user');
        if (m.get(mid)) out.manager_email = m.getValue('email') || '';
      }
    }
    return new global.JSON().encode(out);
  },

  type: 'PCLineUserInfo'
});
